DROP TABLE IF EXISTS `base_code_sequence`;
CREATE TABLE `base_code_sequence`  (
  `sequence_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流水类型, 例如ENTERPRISE/PRODUCT_SPU/PRODUCT_RP/PRODUCT_SKU',
  `prefix` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '编码前缀, 例如ENT/SPU/RP/SKU',
  `current_value` int NOT NULL DEFAULT 0 COMMENT '当前流水值',
  `number_length` tinyint NOT NULL DEFAULT 6 COMMENT '流水号补零长度, 例如6表示000001',
  `remark` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '说明',
  `update_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`sequence_type`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '通用业务编码流水表' ROW_FORMAT = Dynamic;

