-- ----------------------------
-- Table structure for base_enterprise
-- ----------------------------
DROP TABLE IF EXISTS `base_enterprise`;
CREATE TABLE `base_enterprise`  (
  `enterprise_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '企业主体ID, UUID主键',
  `enterprise_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '企业编码, 系统自动生成, 格式ENT000001',
  `enterprise_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '企业名称, 业务展示名称',
  `enterprise_name_normalized` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '企业名称规范化值, 用于唯一性判断',
  `short_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '简称',
  `short_name_normalized` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '简称规范化值, 用于检索',
  `unified_credit_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '统一社会信用代码, 非必填; 填写后唯一',
  `enterprise_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '企业类型, 系统内置枚举: ENTERPRISE/MEDICAL_ORG/INDIVIDUAL/PUBLIC_INSTITUTION/OTHER',
  `contact_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '主联系人',
  `contact_phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '联系电话',
  `address` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '完整地址, 本期不拆省市区',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '启停状态: 0停用, 1启用',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `row_version` int NOT NULL DEFAULT 1 COMMENT '乐观锁版本号, 编辑和启停用',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人用户ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人用户ID',
  `create_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标记; 本期不提供删除, 仅预留存量查询口径',
  PRIMARY KEY (`enterprise_id`) USING BTREE,
  UNIQUE INDEX `uk_base_enterprise_code`(`enterprise_code` ASC) USING BTREE,
  UNIQUE INDEX `uk_base_enterprise_name_norm`(`enterprise_name_normalized` ASC, `del_flag` ASC) USING BTREE,
  UNIQUE INDEX `uk_base_enterprise_credit`(`unified_credit_code` ASC) USING BTREE,
  INDEX `idx_base_enterprise_type`(`enterprise_type` ASC) USING BTREE,
  INDEX `idx_base_enterprise_status`(`status` ASC) USING BTREE,
  INDEX `idx_base_enterprise_update_date`(`update_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '企业主体统一主数据表' ROW_FORMAT = Dynamic;

