-- ----------------------------
-- Table structure for base_institution_contact
-- ----------------------------
DROP TABLE IF EXISTS `base_institution_contact`;
CREATE TABLE `base_institution_contact`  (
  `contact_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '机构联系人内部主键',
  `institution_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属机构资料ID',
  `contact_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '联系人类型',
  `contact_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '联系人姓名',
  `job_title` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '职务',
  `phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '联系电话',
  `email` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '电子邮箱',
  `is_primary` tinyint NOT NULL DEFAULT 0 COMMENT '是否主要联系人：0否，1是',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '联系人备注',
  PRIMARY KEY (`contact_id`) USING BTREE,
  INDEX `idx_base_institution_contact_institution`(`institution_id` ASC) USING BTREE,
  INDEX `idx_base_institution_contact_type`(`institution_id` ASC, `contact_type` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '机构联系资料表' ROW_FORMAT = Dynamic;

