-- ----------------------------
-- Table structure for erp_inventory_balance
-- ----------------------------
DROP TABLE IF EXISTS `erp_inventory_balance`;
CREATE TABLE `erp_inventory_balance`  (
  `balance_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '库存余额ID',
  `warehouse_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '仓库ID',
  `sku_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SKU ID',
  `batch_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '库存批次ID',
  `package_unit_count` int NOT NULL DEFAULT 0 COMMENT '包装单位库存数量',
  `package_unit_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '包装单位名称',
  `min_unit_count` bigint NOT NULL DEFAULT 0 COMMENT '最小单位库存数量',
  `min_unit_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '最小单位名称',
  `row_version` int NOT NULL DEFAULT 1 COMMENT '数据版本号',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人ID',
  `create_date` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_date` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`balance_id`) USING BTREE,
  UNIQUE INDEX `uk_erp_inventory_balance_warehouse_batch`(`warehouse_id` ASC, `batch_id` ASC) USING BTREE,
  INDEX `idx_erp_inventory_balance_warehouse`(`warehouse_id` ASC) USING BTREE,
  INDEX `idx_erp_inventory_balance_sku`(`sku_id` ASC) USING BTREE,
  INDEX `idx_erp_inventory_balance_batch`(`batch_id` ASC) USING BTREE,
  INDEX `idx_erp_inventory_balance_update_date`(`update_date` ASC) USING BTREE,
  INDEX `idx_erp_inventory_balance_owner_date`(`creator_id` ASC, `update_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'ERP库存余额' ROW_FORMAT = Dynamic;

