DROP TABLE IF EXISTS `erp_inventory_batch`;
CREATE TABLE `erp_inventory_batch`  (
  `batch_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '库存批次ID',
  `sku_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SKU ID',
  `batch_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '批号',
  `expiry_date` date NOT NULL COMMENT '有效期',
