  INDEX `idx_erp_warehouse_update_date`(`update_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'ERP仓库基础资料表' ROW_FORMAT = Dynamic;

