-- ----------------------------
-- Table structure for med_diagnosis
-- ----------------------------
DROP TABLE IF EXISTS `med_diagnosis`;
CREATE TABLE `med_diagnosis`  (
  `diagnosis_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '疾病诊断档案ID（UUID）',
  `icd_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ICD编码',
  `icd_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ICD名称',
  `name_pinyin` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'ICD名称拼音',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态：0停用，1启用',
  `sort` int NOT NULL DEFAULT 0 COMMENT '排序号，数值越小越靠前',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人系统用户ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '最后修改人系统用户ID',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_date` datetime NOT NULL COMMENT '最后修改时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标记：0未删除，1已删除',
  `active_icd_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS ((case when (`del_flag` = 0) then `icd_code` else NULL end)) STORED COMMENT '未删除诊断的ICD编码（唯一约束生成列）' NULL,
  PRIMARY KEY (`diagnosis_id`) USING BTREE,
  UNIQUE INDEX `uk_med_diagnosis_active_icd_code`(`active_icd_code` ASC) USING BTREE,
  INDEX `idx_med_diagnosis_status_sort`(`status` ASC, `del_flag` ASC, `sort` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '疾病诊断档案' ROW_FORMAT = Dynamic;

