-- ----------------------------
-- Table structure for med_prescription_item
-- ----------------------------
DROP TABLE IF EXISTS `med_prescription_item`;
CREATE TABLE `med_prescription_item`  (
  `item_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '处方药品明细ID（UUID）',
  `prescription_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '处方ID',
  `sku_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '产品SKU ID',
  `sku_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SKU编码快照',
  `product_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '药品名称快照',
  `spec_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '药品规格快照',
  `dosage_form` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '剂型快照',
  `enterprise_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '生产企业名称快照',
  `approval_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '批准文号快照',
  `package_spec_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '包装规格快照',
  `pack_conversion` int NOT NULL COMMENT '每包装包含的最小单位数量快照',
  `min_unit_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '最小单位名称快照',
  `package_unit_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '包装单位名称快照',
  `allow_split` tinyint NOT NULL DEFAULT 0 COMMENT '是否允许拆零快照：0否，1是',
  `single_dose` decimal(12, 3) NOT NULL COMMENT '单次用量',
  `dose_unit` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '单次用量单位',
  `medication_route` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '给药途径字典值',
  `frequency` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用药频次枚举值',
  `course_days` int NOT NULL COMMENT '疗程天数',
  `total_min_quantity` decimal(14, 3) NOT NULL COMMENT '按最小单位计算的总量',
  `dispense_quantity` decimal(14, 3) NOT NULL COMMENT '最终发药数量',
  `dispense_unit` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '最终发药单位',
  `usage_instructions` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '用药说明',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '明细备注',
  `sort` int NOT NULL DEFAULT 0 COMMENT '处方内排序号',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人系统用户ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '最后修改人系统用户ID',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_date` datetime NOT NULL COMMENT '最后修改时间',
  PRIMARY KEY (`item_id`) USING BTREE,
  UNIQUE INDEX `uk_med_prescription_item_sku`(`prescription_id` ASC, `sku_id` ASC) USING BTREE,
  INDEX `idx_med_prescription_item_sort`(`prescription_id` ASC, `sort` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '处方当前药品明细' ROW_FORMAT = Dynamic;

