-- ----------------------------
-- Table structure for med_registration
-- ----------------------------
DROP TABLE IF EXISTS `med_registration`;
CREATE TABLE `med_registration`  (
  `registration_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '挂号单ID',
  `registration_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '挂号单编号，使用REG前缀业务序列生成',
  `patient_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联患者ID',
  `patient_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '患者编号快照',
  `patient_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '患者姓名快照，敏感信息',
  `patient_gender` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '患者性别字典值快照',
  `patient_birth_date` date NOT NULL COMMENT '患者出生日期快照',
  `patient_id_type` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '患者证件类型字典值快照',
  `patient_id_number` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '患者证件号码快照，敏感信息',
  `patient_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '患者手机号快照，敏感信息',
  `schedule_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联排班ID',
  `slot_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联号源时段ID',
  `doctor_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联医生ID',
  `doctor_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '医生姓名快照',
  `department_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联出诊科室ID',
  `department_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '出诊科室名称快照',
  `schedule_date` date NOT NULL COMMENT '就诊日期快照',
  `start_time` time NOT NULL COMMENT '号源开始时间快照',
  `end_time` time NOT NULL COMMENT '号源结束时间快照',
  `registration_type` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '挂号类型字典值快照',
  `registration_type_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '挂号类型名称快照',
  `registration_method` smallint NOT NULL COMMENT '挂号方式：0现场挂号，10预约挂号',
  `fee_rule_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '挂号费用规则ID快照',
  `fee_rule_version` int NULL DEFAULT NULL COMMENT '挂号费用规则版本快照',
  `fee_amount` decimal(10, 2) NOT NULL COMMENT '挂号费用金额快照',
  `status` smallint NOT NULL DEFAULT 0 COMMENT '挂号状态：0待支付，10已支付，30已签到，50已完成，60已取消，70爽约，80发起退款，90退款中，100退款完成',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建挂号单时填写的备注',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人用户ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '最后更新人用户ID',
  `create_date` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_date` datetime NULL DEFAULT NULL COMMENT '最后更新时间',
  PRIMARY KEY (`registration_id`) USING BTREE,
  UNIQUE INDEX `uk_med_registration_no`(`registration_no` ASC) USING BTREE,
  INDEX `idx_med_registration_patient_slot`(`patient_id` ASC, `slot_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_med_registration_visit_status`(`schedule_date` ASC, `status` ASC) USING BTREE,
