-- ----------------------------
-- Table structure for med_schedule
-- ----------------------------
DROP TABLE IF EXISTS `med_schedule`;
CREATE TABLE `med_schedule`  (
  `schedule_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '实际排班ID',
  `template_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源周期模板ID，手工排班为空',
  `generation_batch_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源生成批次ID',
  `doctor_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '医生ID',
  `department_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '出诊科室ID',
  `registration_type` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '挂号类型，字典MED_REGISTRATION_TYPE',
  `schedule_date` date NOT NULL COMMENT '出诊日期',
  `start_time` time NOT NULL COMMENT '开始时间',
  `end_time` time NOT NULL COMMENT '结束时间',
  `fee_rule_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '发布时固化的挂号费规则ID',
  `fee_rule_version` int NULL DEFAULT NULL COMMENT '发布时固化的规则版本',
  `fee_amount` decimal(10, 2) NULL DEFAULT NULL COMMENT '发布时固化的挂号费金额（元）',
  `default_slot_quota` int NOT NULL DEFAULT 1 COMMENT '草稿生成时每半小时默认容量',
  `total_quota` int NOT NULL COMMENT '号源总量',
  `booked_quota` int NOT NULL DEFAULT 0 COMMENT '已预约号源数',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态 0草稿 1已发布 2停诊 3结束',
  `stop_reason` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '停诊原因',
  `published_at` datetime NULL DEFAULT NULL COMMENT '发布时间',
  `stopped_at` datetime NULL DEFAULT NULL COMMENT '停诊时间',
  `finished_at` datetime NULL DEFAULT NULL COMMENT '结束时间',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人ID',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标记 0正常 1删除',
  PRIMARY KEY (`schedule_id`) USING BTREE,
  UNIQUE INDEX `uk_med_schedule_template_date`(`template_id` ASC, `schedule_date` ASC) USING BTREE,
  INDEX `idx_med_schedule_doctor_conflict`(`doctor_id` ASC, `schedule_date` ASC, `status` ASC, `del_flag` ASC, `start_time` ASC, `end_time` ASC) USING BTREE,
  INDEX `idx_med_schedule_department_date`(`department_id` ASC, `schedule_date` ASC, `status` ASC, `del_flag` ASC) USING BTREE,
  INDEX `idx_med_schedule_batch`(`generation_batch_id` ASC) USING BTREE,
  INDEX `idx_med_schedule_fee_rule`(`fee_rule_id` ASC, `fee_rule_version` ASC) USING BTREE,
  INDEX `idx_med_schedule_owner_active`(`creator_id` ASC, `del_flag` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '实际排班及费用号源快照' ROW_FORMAT = Dynamic;

