-- ----------------------------
-- Table structure for med_schedule_auto_task
-- ----------------------------
DROP TABLE IF EXISTS `med_schedule_auto_task`;
CREATE TABLE `med_schedule_auto_task`  (
  `task_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '自动任务记录ID',
  `task_key` varchar(96) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任务幂等键：任务类型+目标周',
  `task_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任务类型 publish发布 generate生成',
  `target_week_start` date NOT NULL COMMENT '目标周开始日期（周一）',
  `target_week_end` date NOT NULL COMMENT '目标周结束日期（周日）',
  `status` tinyint NOT NULL COMMENT '状态 0成功 1部分成功 2失败 3执行中',
  `success_doctor_count` int NOT NULL DEFAULT 0 COMMENT '成功医生数',
  `failure_doctor_count` int NOT NULL DEFAULT 0 COMMENT '失败医生数',
  `details` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '失败医生及原因JSON',
  `executed_at` datetime NOT NULL COMMENT '执行时间',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`task_id`) USING BTREE,
  UNIQUE INDEX `uk_med_schedule_auto_task_key`(`task_key` ASC) USING BTREE,
  INDEX `idx_med_schedule_auto_task_week`(`target_week_start` ASC, `task_type` ASC, `status` ASC) USING BTREE,
  INDEX `idx_med_schedule_auto_task_executed`(`executed_at` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '出诊排班每周自动发布和生成任务记录' ROW_FORMAT = Dynamic;

