-- ----------------------------
-- Table structure for med_schedule_slot
-- ----------------------------
DROP TABLE IF EXISTS `med_schedule_slot`;
CREATE TABLE `med_schedule_slot`  (
  `slot_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '号源档位ID',
  `schedule_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '出诊排班ID',
  `start_time` time NOT NULL COMMENT '档位开始时间',
  `end_time` time NOT NULL COMMENT '档位结束时间',
  `quota` int NOT NULL COMMENT '档位可预约容量 0至99',
  `booked_quota` int NOT NULL DEFAULT 0 COMMENT '已预约数量',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人ID',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标记 0正常 1删除',
  PRIMARY KEY (`slot_id`) USING BTREE,
  UNIQUE INDEX `uk_med_schedule_slot_time`(`schedule_id` ASC, `start_time` ASC, `del_flag` ASC) USING BTREE,
  INDEX `idx_med_schedule_slot_available`(`schedule_id` ASC, `start_time` ASC, `quota` ASC, `booked_quota` ASC, `del_flag` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '出诊排班半小时预约号源档位' ROW_FORMAT = Dynamic;

