-- ----------------------------
-- Table structure for med_schedule_template
-- ----------------------------
DROP TABLE IF EXISTS `med_schedule_template`;
CREATE TABLE `med_schedule_template`  (
  `template_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '周期排班模板ID',
  `template_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板名称',
  `doctor_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '医生ID',
  `department_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '出诊科室ID',
  `registration_type` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '挂号类型，字典MED_REGISTRATION_TYPE',
  `weekday` tinyint NOT NULL COMMENT '星期 1周一至7周日',
  `start_time` time NOT NULL COMMENT '开始时间',
  `end_time` time NOT NULL COMMENT '结束时间',
  `default_slot_quota` int NOT NULL DEFAULT 1 COMMENT '每半小时默认号源容量',
  `slot_quota_config` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '单档容量覆盖JSON',
  `total_quota` int NOT NULL COMMENT '模板号源总量',
  `effective_date` date NOT NULL COMMENT '模板生效日期（含）',
  `expiry_date` date NULL DEFAULT NULL COMMENT '模板失效日期（含），NULL表示长期有效',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态 0停用 1启用',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人ID',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标记 0正常 1删除',
  PRIMARY KEY (`template_id`) USING BTREE,
  INDEX `idx_med_schedule_template_doctor`(`doctor_id` ASC, `weekday` ASC, `status` ASC, `del_flag` ASC, `effective_date` ASC, `expiry_date` ASC) USING BTREE,
  INDEX `idx_med_schedule_template_department`(`department_id` ASC, `status` ASC, `del_flag` ASC) USING BTREE,
  INDEX `idx_med_schedule_template_period`(`effective_date` ASC, `expiry_date` ASC, `status` ASC, `del_flag` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '周期排班模板' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of med_schedule_template
-- ----------------------------
INSERT INTO `med_schedule_template` VALUES ('ec27638e-9bf5-43f9-a2f9-8a0cffd4f0cf', '王医生自动排班周一、周二、周三', '322c164d-af9e-4f57-9899-8ec355757b6c', 'a8598885-79b6-424b-9609-01c3db8e5504', '1', 1, '14:00:00', '22:00:00', 1, NULL, 16, '2026-07-18', NULL, 1, NULL, 'cc1a8564-37e7-47df-ad60-6c0a7f199d31', 'cc1a8564-37e7-47df-ad60-6c0a7f199d31', '2026-07-18 11:41:47', '2026-07-18 11:43:52', 0);
INSERT INTO `med_schedule_template` VALUES ('f579820b-2a19-420d-a823-7cdf9d354e24', '王医生自动排班周一、周三、周五', '322c164d-af9e-4f57-9899-8ec355757b6c', 'a8598885-79b6-424b-9609-01c3db8e5504', '1', 1, '08:00:00', '12:00:00', 2, '[{\"startTime\":\"09:00\",\"quota\":99}]', 113, '2026-07-01', NULL, 1, NULL, 'cc1a8564-37e7-47df-ad60-6c0a7f199d31', 'cc1a8564-37e7-47df-ad60-6c0a7f199d31', '2026-07-18 11:34:42', '2026-07-18 11:45:28', 0);

