-- Table structure for med_schedule_template_weekday
-- ----------------------------
DROP TABLE IF EXISTS `med_schedule_template_weekday`;
CREATE TABLE `med_schedule_template_weekday`  (
  `template_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '周期排班模板ID',
