  PRIMARY KEY (`template_id`, `weekday`) USING BTREE,
  INDEX `idx_med_schedule_template_weekday`(`weekday` ASC, `template_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '周期排班模板适用星期' ROW_FORMAT = Dynamic;

