-- ----------------------------
-- Table structure for med_visit_queue
-- ----------------------------
DROP TABLE IF EXISTS `med_visit_queue`;
CREATE TABLE `med_visit_queue`  (
  `queue_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '候诊记录ID（UUID）',
  `registration_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '挂号单ID',
  `schedule_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '实际排班ID，作为候诊队列边界',
  `queue_sequence` int UNSIGNED NOT NULL COMMENT '签到序号，同一实际排班内从1递增',
  `queue_status` smallint NOT NULL DEFAULT 0 COMMENT '候诊状态：0-候诊中，30-已完成',
  `call_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '叫号次数',
  `create_date` datetime NOT NULL COMMENT '候诊记录创建时间，即签到排号时间',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人系统用户ID',
  PRIMARY KEY (`queue_id`) USING BTREE,
  UNIQUE INDEX `uk_med_visit_queue_registration`(`registration_id` ASC) USING BTREE,
  UNIQUE INDEX `uk_med_visit_queue_schedule_sequence`(`schedule_id` ASC, `queue_sequence` ASC) USING BTREE,
  INDEX `idx_med_visit_queue_schedule_status_sequence`(`schedule_id` ASC, `queue_status` ASC, `queue_sequence` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '挂号单候诊队列表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of med_visit_queue
