-- ----------------------------
-- Table structure for print_template
-- ----------------------------
DROP TABLE IF EXISTS `print_template`;
CREATE TABLE `print_template`  (
  `template_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '打印模板唯一标识',
  `document_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务单据类型，例如 PURCHASE_INBOUND；同一种单据类型只允许存在一条模板记录',
  `template_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '打印模板名称',
  `draft_layout` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '当前编辑中的模板布局草稿，保存模板版式、字段绑定、分页等设计数据',
  `published_layout` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '当前已发布并实际生效的模板布局；未发布时为空',
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板状态：DRAFT-草稿，PUBLISHED-已发布',
  `row_version` int NOT NULL DEFAULT 1 COMMENT '数据行版本号，用于并发更新时进行乐观锁校验',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人用户标识',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '最后更新人用户标识',
  `create_date` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_date` datetime NULL DEFAULT NULL COMMENT '最后更新时间',
  PRIMARY KEY (`template_id`) USING BTREE,
  UNIQUE INDEX `uk_print_template_document_type`(`document_type` ASC) USING BTREE,
  INDEX `idx_print_template_status`(`status` ASC) USING BTREE,
  INDEX `idx_print_template_update_date`(`update_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '业务单据打印模板；每种单据类型仅维护一条当前模板记录，不保存历史版本' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of print_template
-- ----------------------------

-- ----------------------------
-- Table structure for product_mp
-- ----------------------------
DROP TABLE IF EXISTS `product_mp`;
CREATE TABLE `product_mp`  (
  `mp_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '厂家产品ID',
  `mp_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'MP编码',
  `rp_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属规格产品ID',
  `enterprise_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '生产企业ID',
  `approval_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '批准文号/注册证号/备案号',
  `approval_no_normalized` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '批准文号标准化值',
  `brand_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '品牌/商品名',
  `description` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '描述',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态: 0停用 1启用',
  `row_version` int NOT NULL DEFAULT 1 COMMENT '数据版本号',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人ID',
  `create_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标记: 0正常 1删除',
  PRIMARY KEY (`mp_id`) USING BTREE,
  UNIQUE INDEX `uk_product_mp_code`(`mp_code` ASC) USING BTREE,
  UNIQUE INDEX `uk_product_mp_rp_enterprise_approval`(`rp_id` ASC, `enterprise_id` ASC, `approval_no_normalized` ASC, `del_flag` ASC) USING BTREE,
  INDEX `idx_product_mp_rp_status`(`rp_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_product_mp_enterprise`(`enterprise_id` ASC) USING BTREE,
  INDEX `idx_product_mp_update_date`(`update_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '厂家产品主数据表' ROW_FORMAT = Dynamic;

