-- ----------------------------
-- Table structure for product_sku
-- ----------------------------
DROP TABLE IF EXISTS `product_sku`;
CREATE TABLE `product_sku`  (
  `sku_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SKU ID',
  `sku_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SKU编码',
  `mp_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属厂家产品ID',
  `package_spec_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '包装规格名称',
  `package_spec_name_normalized` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '包装规格名称标准归一化值(去空格/拼接/转小写)',
  `pack_conversion` int NOT NULL COMMENT '包装换算系数: 1个包装单位包含的最小单位数量',
  `min_unit_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '最小单位名称',
  `package_unit_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '包装单位名称',
  `carton_unit_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '大包装单位名称',
  `carton_conversion` int NOT NULL DEFAULT 1 COMMENT '大包装换算系数: 1个大包装单位包含的包装单位数量',
  `carton_spec_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '大包装规格名称',
  `full_chain_spec_name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '全链路规格名称',
  `barcode` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '商品条码',
  `gtin` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'GTIN',
  `udi_di` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'UDI-DI',
  `allow_split` tinyint NOT NULL DEFAULT 0 COMMENT '是否允许拆零: 0否 1是',
  `trace_mode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NONE' COMMENT '追溯模式：NONE不启用追溯、SMALL按小码追溯',
  `description` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '描述',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态: 0停用 1启用',
  `row_version` int NOT NULL DEFAULT 1 COMMENT '数据版本号',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人ID',
  `create_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标记: 0正常 1删除',
  PRIMARY KEY (`sku_id`) USING BTREE,
  UNIQUE INDEX `uk_product_sku_code`(`sku_code` ASC) USING BTREE,
  UNIQUE INDEX `uk_product_sku_mp_package_spec`(`mp_id` ASC, `package_spec_name_normalized` ASC, `del_flag` ASC) USING BTREE,
  INDEX `idx_product_sku_mp`(`mp_id` ASC) USING BTREE,
  INDEX `idx_product_sku_mp_status`(`mp_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_product_sku_status`(`status` ASC) USING BTREE,
  INDEX `idx_product_sku_update_date`(`update_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '包装品规主数据' ROW_FORMAT = Dynamic;

