-- ----------------------------
-- Table structure for product_sku_price_tier
-- ----------------------------
DROP TABLE IF EXISTS `product_sku_price_tier`;
CREATE TABLE `product_sku_price_tier`  (
  `tier_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SKU价格阶梯ID',
  `price_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属SKU价格ID',
  `min_quantity` int NOT NULL COMMENT '起始数量，按SKU包装单位计算',
  `max_quantity` int NULL DEFAULT NULL COMMENT '结束数量，空表示以上',
  `tier_price` decimal(18, 4) NOT NULL COMMENT '阶梯单价',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人ID',
  `create_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标记: 0正常 1删除',
  PRIMARY KEY (`tier_id`) USING BTREE,
  INDEX `idx_product_sku_price_tier_price`(`price_id` ASC, `del_flag` ASC) USING BTREE,
  INDEX `idx_product_sku_price_tier_min`(`price_id` ASC, `min_quantity` ASC, `del_flag` ASC) USING BTREE,
  INDEX `idx_product_sku_price_tier_update_date`(`update_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'SKU价格阶梯表' ROW_FORMAT = Dynamic;

