-- ----------------------------
-- Table structure for sys_download_task
-- ----------------------------
DROP TABLE IF EXISTS `sys_download_task`;
CREATE TABLE `sys_download_task`  (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '任务ID',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '创建用户ID',
  `task_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '导出任务类型',
  `task_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '任务名称',
  `source_module` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '来源模块',
  `request_payload` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '导出条件JSON',
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'pending/running/succeeded/failed',
  `total_rows` bigint NOT NULL DEFAULT 0 COMMENT '总行数',
  `processed_rows` bigint NOT NULL DEFAULT 0 COMMENT '已处理行数',
  `progress` tinyint NOT NULL DEFAULT 0 COMMENT '进度百分比',
  `file_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '下载文件名',
  `file_path` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '服务器私有文件路径',
  `file_size` bigint NOT NULL DEFAULT 0 COMMENT '文件字节数',
  `error_message` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '失败原因',
  `completed_date` datetime NULL DEFAULT NULL COMMENT '完成时间',
  `expire_date` datetime NULL DEFAULT NULL COMMENT '文件过期时间',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_download_creator_created`(`creator_id` ASC, `create_date` ASC) USING BTREE,
  INDEX `idx_download_status_created`(`status` ASC, `create_date` ASC) USING BTREE,
  INDEX `idx_download_expire_date`(`expire_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '下载中心任务' ROW_FORMAT = Dynamic;

