-- ----------------------------
-- Table structure for sys_form_schema
-- ----------------------------
DROP TABLE IF EXISTS `sys_form_schema`;
CREATE TABLE `sys_form_schema`  (
  `form_schema_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '表单Schema ID',
  `schema_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Schema唯一标识',
  `schema_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Schema名称',
  `category` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类',
  `layout` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'single' COMMENT '表单布局 single单列 double双列 triple三列',
  `schema_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '可持久化Vben Form Schema JSON',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态 0禁用 1启用',
  `remark` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `create_date` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_date` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标记 0正常 1删除',
  PRIMARY KEY (`form_schema_id`) USING BTREE,
  UNIQUE INDEX `uk_sys_form_schema_key`(`schema_key` ASC) USING BTREE,
  INDEX `idx_sys_form_schema_status`(`status` ASC, `del_flag` ASC) USING BTREE,
  INDEX `idx_sys_form_schema_category`(`category` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '独立表单Schema' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_form_schema
-- ----------------------------
INSERT INTO `sys_form_schema` VALUES ('aad9bce9-0958-41cd-9f40-7780188fd371', 'baoxiao', '报销表单', '财务', 'double', '[{\"component\":\"Input\",\"componentProps\":{\"allowClear\":true},\"fieldName\":\"desc\",\"formItemClass\":\"col-span-1 items-baseline\",\"label\":\"理由\",\"rules\":[{\"type\":\"string\",\"max\":500,\"min\":2}]},{\"component\":\"InputNumber\",\"componentProps\":{},\"fieldName\":\"amount\",\"formItemClass\":\"col-span-1 items-baseline\",\"label\":\"报销金额\",\"rules\":[{\"type\":\"number\",\"min\":100,\"max\":10000}]},{\"component\":\"Upload\",\"componentProps\":{},\"defaultValue\":[],\"fieldName\":\"img\",\"formItemClass\":\"col-span-1 items-baseline\",\"label\":\"发票\"},{\"component\":\"Input\",\"componentProps\":{\"allowClear\":true},\"fieldName\":\"input1\",\"formItemClass\":\"col-span-1 items-baseline\",\"label\":\"单行文本\"}]', 1, '我是备注', '54323cef-fbdb-4b6e-90bf-8e6a9aefd7c0', '2026-07-16 00:40:11', '2026-07-16 18:53:19', 0);

-- ----------------------------
-- Table structure for sys_login_log
-- ----------------------------
DROP TABLE IF EXISTS `sys_login_log`;
CREATE TABLE `sys_login_log`  (
  `log_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `user_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `username` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '',
  `event_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `response_body` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `response_truncated` tinyint NOT NULL DEFAULT 0,
  `http_status` int NOT NULL,
  `status` tinyint NOT NULL,
  `duration_ms` bigint NOT NULL DEFAULT 0,
  `ip` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '',
  `user_agent` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '',
  `content_type` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '',
  `create_date` datetime NOT NULL,
  PRIMARY KEY (`log_id`) USING BTREE,
  INDEX `idx_login_log_create_date`(`create_date` ASC) USING BTREE,
  INDEX `idx_login_log_status_date`(`status` ASC, `create_date` ASC) USING BTREE,
  INDEX `idx_login_log_username_date`(`username` ASC, `create_date` ASC) USING BTREE,
  INDEX `idx_login_log_ip_date`(`ip` ASC, `create_date` ASC) USING BTREE,
  INDEX `idx_sys_login_log_owner_date`(`user_id` ASC, `create_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '登录日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_login_log
-- ----------------------------

-- ----------------------------
-- Table structure for sys_menu
-- ----------------------------
DROP TABLE IF EXISTS `sys_menu`;
CREATE TABLE `sys_menu`  (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '菜单id,主键,UUID格式',
  `pid` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '上级菜单',
  `type` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '菜单类型,字典',
  `icon` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '图标',
  `active_icon` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '激活图标',
  `keep_alive` tinyint NULL DEFAULT 0 COMMENT '缓存标签页,0不缓存,1缓存',
  `hide_in_menu` tinyint NULL DEFAULT 0 COMMENT '在菜单中隐藏,0不隐藏,1隐藏',
  `hide_in_tab` tinyint NULL DEFAULT 0 COMMENT '在标签栏中隐藏,0不隐藏,1隐藏',
  `hide_in_breadcrumb` tinyint NULL DEFAULT 0 COMMENT '在面包屑中隐藏,0不隐藏,1隐藏',
  `hide_children_in_menu` tinyint NULL DEFAULT 0 COMMENT '隐藏子菜单0不隐藏,1隐藏',
  `badge` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '徽章内容',
  `badge_type` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '徽标类型',
  `badge_variants` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '徽标样式',
  `active_path` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '激活路径',
  `auth_code` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '权限码集合，多个权限码使用英文逗号分隔',
  `affix_tab` tinyint NULL DEFAULT 0 COMMENT '固定在标签0不固定,1固定',
  `component` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '页面组件路径',
  `title` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标题',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '路由名称，按钮为空',
  `path` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '路由地址',
  `status` tinyint NULL DEFAULT 1 COMMENT '状态1启用0禁用',
  `link` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '外链跳转路径',
  `iframe_src` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '内嵌页面的 iframe 地址',
  `order` tinyint NULL DEFAULT 0 COMMENT '用于路由->菜单排序',
  `max_num_of_open_tab` tinyint NULL DEFAULT NULL COMMENT '标签页最大打开数量(仅在打开同名标签页时生效)',
  `affix_tab_order` tinyint NULL DEFAULT 0 COMMENT '固定标签页的排序',
  `no_basic_layout` tinyint NULL DEFAULT 0 COMMENT '无基础布局，0=否 1=是',
  `ignore_access` tinyint NOT NULL DEFAULT 0 COMMENT '是否忽略访问鉴权：0否，1是',
  `open_in_new_window` tinyint NULL DEFAULT 0 COMMENT '在新窗口打开页面 0=否 1=是',
  `dom_cached` tinyint NULL DEFAULT 0 COMMENT '用于配置当前路由是否要将route对应dom元素缓存起来 0=否 1=是',
  `query` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '额外的路由参数',
  `menu_visible_with_forbidden` tinyint NULL DEFAULT 0 COMMENT '菜单可以看到，但是访问会被重定向到403',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人id',
  `creator_name` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人姓名',
  `create_date` datetime NULL DEFAULT NULL COMMENT '创建日期',
  `update_date` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `del_flag` tinyint NULL DEFAULT 0 COMMENT '逻辑删除 0:正常  1:删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '系统权限菜单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_menu
-- ----------------------------
