  `title` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '实例标题',
  `business_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联业务唯一标识',
  `starter_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发起人id',
  `starter_name` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发起人名称快照',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态:0运行中 1已完成 2已驳回 3已撤销',
  `variables` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程变量JSON',
  `flow_snapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程定义画布快照',
  `form_snapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '发起时的流程表单结构快照JSON',
  `form_layout` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'single' COMMENT '发起时的表单布局快照',
  `start_date` datetime NULL DEFAULT NULL COMMENT '开始时间',
  `end_date` datetime NULL DEFAULT NULL COMMENT '结束时间',
  `create_date` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_date` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0正常 1删除',
  PRIMARY KEY (`instance_id`) USING BTREE,
  UNIQUE INDEX `uk_wf_process_instance_no`(`instance_no` ASC) USING BTREE,
  INDEX `idx_wf_instance_definition_id`(`definition_id` ASC) USING BTREE,
  INDEX `idx_wf_instance_business_key`(`business_key` ASC) USING BTREE,
  INDEX `idx_wf_instance_starter_id`(`starter_id` ASC) USING BTREE,
  INDEX `idx_wf_instance_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '流程实例表' ROW_FORMAT = Dynamic;

