-- ----------------------------
-- Table structure for wf_process_instance_sequence
-- ----------------------------
DROP TABLE IF EXISTS `wf_process_instance_sequence`;
CREATE TABLE `wf_process_instance_sequence`  (
  `prefix` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程分类前缀',
  `business_date` date NOT NULL COMMENT '业务日期',
  `current_value` int UNSIGNED NOT NULL COMMENT '当前流水号',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`prefix`, `business_date`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '流程实例编号每日流水' ROW_FORMAT = Dynamic;

