-- ----------------------------
-- Table structure for wf_process_node_instance
-- ----------------------------
DROP TABLE IF EXISTS `wf_process_node_instance`;
CREATE TABLE `wf_process_node_instance`  (
  `node_instance_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '节点实例ID',
  `instance_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程实例ID',
  `node_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程节点ID',
  `node_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程节点名称快照',
  `node_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '节点类型',
  `sequence` int NOT NULL COMMENT '实例内展示顺序',
  `route_version` int NOT NULL COMMENT '路径版本',
  `status` tinyint NOT NULL COMMENT '0预计 1处理中 2完成 3终止 4已替换',
  `approval_mode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '审批方式 any/all',
  `branch_edge_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '条件节点命中连线ID',
  `actor_ids` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '预计参与人ID数组JSON',
  `actor_names` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '预计参与人名称数组JSON',
  `field_permissions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '节点字段权限快照JSON',
  `start_date` datetime NULL DEFAULT NULL COMMENT '节点到达时间',
  `end_date` datetime NULL DEFAULT NULL COMMENT '节点结束时间',
  `create_date` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_date` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`node_instance_id`) USING BTREE,
  INDEX `idx_wf_node_instance_instance_sequence`(`instance_id` ASC, `sequence` ASC) USING BTREE,
  INDEX `idx_wf_node_instance_instance_status`(`instance_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_wf_node_instance_route`(`instance_id` ASC, `route_version` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '流程节点实例' ROW_FORMAT = Dynamic;

